def resolve(path, cwd, links):
    """
    Resolve a path to its canonical absolute path, handling symlinks.

    Args:
        path: The path to resolve (absolute or relative to cwd)
        cwd: The current working directory (canonical absolute path)
        links: Dict mapping canonical absolute paths to symlink targets

    Returns:
        The canonical absolute path, or None on error
    """

    # Start with absolute path
    if path.startswith('/'):
        current = '/'
        remaining = path[1:]
    else:
        current = cwd
        remaining = path

    link_count = 0
    max_links = 8

    while True:
        # Split remaining path into components
        if remaining == '':
            components = []
        else:
            components = remaining.split('/')

        # Process components left to right
        remaining = ''

        for component in components:
            # Skip empty components and '.'
            if component == '' or component == '.':
                continue

            # Handle '..'
            if component == '..':
                # Move to parent directory
                if current != '/':
                    current = current.rsplit('/', 1)[0]
                    if current == '':
                        current = '/'
                continue

            # Append component to current path
            if current == '/':
                candidate = '/' + component
            else:
                candidate = current + '/' + component

            # Check if this path is a symlink
            if candidate in links:
                link_count += 1
                if link_count > max_links:
                    return None

                target = links[candidate]

                # If target is absolute, start from root
                if target.startswith('/'):
                    current = '/'
                    remaining = target[1:]
                else:
                    # Target is relative to the directory containing the link
                    current = candidate.rsplit('/', 1)[0]
                    if current == '':
                        current = '/'
                    remaining = target

                # Add any remaining components after this one
                remaining_components = components[components.index(component) + 1:]
                if remaining_components:
                    if remaining:
                        remaining += '/' + '/'.join(remaining_components)
                    else:
                        remaining = '/'.join(remaining_components)

                # Break to restart processing with new current and remaining
                break
            else:
                # Normal directory component
                current = candidate
        else:
            # All components processed without hitting a symlink
            break

    # Return result (no trailing slash except for '/')
    if current == '':
        current = '/'

    return current

